"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[50970],{74538:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>r,contentTitle:()=>s,default:()=>c,frontMatter:()=>a,metadata:()=>i,toc:()=>d});var o=n(31085),h=n(71184);const a={sidebar_position:15,slug:"/bible/1_Kings/1_Kings_15",title:"1 Kings 15",hide_table_of_contents:!0},s="1 Kings",i={id:"bible/1 Kings/1 Kings 15",title:"1 Kings 15",description:"Chapter 15",source:"@site/docs/bible/1 Kings/1 Kings 15.md",sourceDirName:"bible/1 Kings",slug:"/bible/1_Kings/1_Kings_15",permalink:"/bibleNotes/docs/bible/1_Kings/1_Kings_15",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/1 Kings/1 Kings 15.md",tags:[],version:"current",sidebarPosition:15,frontMatter:{sidebar_position:15,slug:"/bible/1_Kings/1_Kings_15",title:"1 Kings 15",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"1 Kings 14",permalink:"/bibleNotes/docs/bible/1_Kings/1_Kings_14"},next:{title:"1 Kings 16",permalink:"/bibleNotes/docs/bible/1_Kings/1_Kings_16"}},r={},d=[{value:"Chapter 15",id:"chapter-15",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,h.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.h1,{id:"1-kings",children:"1 Kings"}),"\n",(0,o.jsx)(t.h2,{id:"chapter-15",children:"Chapter 15"}),"\n",(0,o.jsx)(t.p,{children:"Saul is sent to destroy Amalec:  he spareth their king and the best of their cattle:  for which disobedience he is cast off by the Lord."}),"\n",(0,o.jsx)(n,{verse:1,children:"And Samuel said to Saul: The Lord sent me to anoint thee king over his people Israel: now therefore hearken thou unto the voice of the Lord:"}),"\n",(0,o.jsx)(n,{verse:2,children:"Thus saith the Lord of hosts: I have reckoned up all that Amalec hath done to Israel: how he opposed them in the way when they came up out of Egypt."}),"\n",(0,o.jsx)(n,{verse:3,children:"Now therefore go, and smite Amalec, and utterly destroy all that he hath: spare him not, nor covet anything that is his: but slay both man and woman, child and suckling, ox and sheep, camel and ass."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: Child...The great Master of life and death (who cuts off one half of all mankind whilst they are children) has been pleased sometimes to ordain that children should be put to the sword, in detestation of the crimes of their parents, and that they might not live to follow the same wicked ways. But without such ordinance of God it is not allowable, in any wars, how just soever, to kill children."})}),"\n",(0,o.jsx)(n,{verse:4,children:"So Saul commanded the people, and numbered them as lambs: two hundred thousand footmen, and ten thousand of the men of Juda."}),"\n",(0,o.jsx)(n,{verse:5,children:"And when Saul was come to the city of Amalec, he laid ambushes in the torrent."}),"\n",(0,o.jsx)(n,{verse:6,children:"And Saul said to the Cinite: Go, depart, and get ye down from Amalec: lest I destroy thee with him. For thou hast shewn kindness to all the children of Israel, when they came up out of Egypt. And the Cinite departed from the midst of Amalec."}),"\n",(0,o.jsx)(n,{verse:7,children:"And Saul smote Amalec from Hevila, until thou comest to Sur, which is over against Egypt."}),"\n",(0,o.jsx)(n,{verse:8,children:"And he took Agag, the king of Amalec, alive: but all the common people he slew with the edge of the sword."}),"\n",(0,o.jsx)(n,{verse:9,children:"And Saul and the people spared Agag, and the best of the flocks of sheep, and of the herds, and the garments and the rams, and all that was beautiful, and would not destroy them: but every thing that was vile, and good for nothing, that they destroyed."}),"\n",(0,o.jsx)(n,{verse:10,children:"And the word of the Lord came to Samuel,"}),"\n",(0,o.jsx)(n,{verse:11,children:"It repenteth me that I have made Saul king: for he hath forsaken me, and hath not executed my commandments. And Samuel was grieved, and he cried unto the Lord all night."}),"\n",(0,o.jsx)(n,{verse:12,children:"And when Samuel rose early, to go to Saul in the morning, it was told Samuel that Saul was come to Carmel, and had erected for himself a triumphant arch, and returning had passed on, and gone down to Galgal. And Samuel came to Saul, and Saul was offering a holocaust to the Lord, out of the choicest of the spoils, which he had brought from Amalec."}),"\n",(0,o.jsx)(n,{verse:13,children:"And when Samuel was come to Saul, Saul said to him: Blessed be thou of the Lord, I have fulfilled the word of the Lord."}),"\n",(0,o.jsx)(n,{verse:14,children:"And Samuel said: What meaneth then this bleating of the flocks, which soundeth in my ears, and the lowing of the herds, which I hear?"}),"\n",(0,o.jsx)(n,{verse:15,children:"And Saul said: They have brought them from Amalec: for the people spared the best of the sheep and of the herds, that they might be sacrificed to the Lord thy God, but the rest we have slain."}),"\n",(0,o.jsx)(n,{verse:16,children:"And Samuel said to Saul: Suffer me, and I will tell thee what the Lord hath said to me this night. And he said to him: Speak."}),"\n",(0,o.jsx)(n,{verse:17,children:"And Samuel said: When thou wast a little one in thy own eyes, wast thou not made the head of the tribes of Israel? And the Lord anointed thee to be king over Israel."}),"\n",(0,o.jsx)(n,{verse:18,children:"And the Lord sent thee on the way, and said: Go, and kill the sinners of Amalec, and thou shalt fight against them until thou hast utterly destroyed them."}),"\n",(0,o.jsx)(n,{verse:19,children:"Why then didst thou not hearken to the voice of the Lord: but hast turned to the prey, and hast done evil in the eyes of the Lord?"}),"\n",(0,o.jsx)(n,{verse:20,children:"And Saul said to Samuel: Yea, I have hearkened to the voice of the Lord, and have walked in the way by which the Lord sent me, and have brought Agag, the king of Amalec, and Amalec I have slain."}),"\n",(0,o.jsx)(n,{verse:21,children:"But the people took of the spoils, sheep and oxen, as the firstfruits of those things that were slain, to offer sacrifice to the Lord their God in Galgal."}),"\n",(0,o.jsx)(n,{verse:22,children:"And Samuel said: Doth the Lord desire holocausts and victims, and not rather that the voice of the Lord should be obeyed? For obedience is better than sacrifices: and to hearken rather than to offer the fat or rams."}),"\n",(0,o.jsx)(n,{verse:23,children:"Because it is like the sin of witchcraft, to rebel: and like the crime of idolatry, to refuse to obey. Forasmuch, therefore, as thou hast rejected the word of the Lord, the Lord hath also rejected thee from being king."}),"\n",(0,o.jsx)(n,{verse:24,children:"And Saul said to Samuel: I have sinned, because I have transgressed the commandment of the Lord, and thy words, fearing the people, and obeying their voice."}),"\n",(0,o.jsx)(n,{verse:25,children:"But now bear, I beseech thee, my sin, and return with me, that I may adore the Lord."}),"\n",(0,o.jsx)(n,{verse:26,children:"And Samuel said to Saul: I will not return with thee, because thou hath rejected the word of the Lord, and the Lord hath rejected thee from being king over Israel."}),"\n",(0,o.jsx)(n,{verse:27,children:"And Samuel turned about to go away: but he laid hold upon the skirt of his mantle, and it rent."}),"\n",(0,o.jsx)(n,{verse:28,children:"And Samuel said to him: The Lord hath rent the kingdom of Israel from thee this day, and hath given it to thy neighbour who is better than thee."}),"\n",(0,o.jsx)(n,{verse:29,children:"But the triumpher in Israel will not spare, and will not be moved to repentance: for he is not a man that he should repent."}),"\n",(0,o.jsx)(n,{verse:30,children:"Then he said: I have sinned: yet honour me now before the ancients of my people, and before Israel, and return with me, that I may adore the Lord thy God."}),"\n",(0,o.jsx)(n,{verse:31,children:"So Samuel turned again after Saul: and Saul adored the Lord."}),"\n",(0,o.jsx)(n,{verse:32,children:"And Samuel said: Bring hither to me Agag, the king of Amalec. And Agag was presented to him very fat, and trembling. And Agag said: Doth bitter death separate in this manner?"}),"\n",(0,o.jsx)(n,{verse:33,children:"And Samuel said: As thy sword hath made women childless, so shall thy mother be childless among women. And Samuel hewed him in pieces before the Lord in Galgal."}),"\n",(0,o.jsx)(n,{verse:34,children:"And Samuel departed to Ramatha: but Saul went up to his house in Gabaa."}),"\n",(0,o.jsx)(n,{verse:35,children:"And Samuel saw Saul no more till the day of his death: nevertheless, Samuel mourned for Saul, because the Lord repented that he had made him king over Israel."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: Saw Saul no more till the day of his death...That is, he went no more to see him: he visited him no more."})})]})}function c(e={}){const{wrapper:t}={...(0,h.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>i});var o=n(14041);const h={},a=o.createContext(h);function s(e){const t=o.useContext(a);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(h):e.components||h:s(e.components),o.createElement(a.Provider,{value:t},e.children)}}}]);